        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "Custo da linha base declarado como R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O valor do apoio depende do término do marco, que não pode ser determinado sem as precedências da ficha d_a70f."
    ],
    "motivo": "As parcelas fixas são conhecidas, mas o componente de extensão do apoio depende da duração final.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Sem o término novo do marco não se pode calcular a variação da extensão do apoio."
    ],
    "motivo": "A política sem crédito mantém o valor contratado em caso de antecipação, mas a magnitude da extensão após o aviso depende do término ainda indeterminado.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A linha base fornece D12 e R$ 1.650,00. O aviso altera a restrição do dossiê de D8 para D10, mas a view não fornece as precedências da ficha referenciada; não se presume a ligação dessa atividade ao marco final. Como o apoio varia com o término do marco, também não é possível determinar o custo novo nem sua variação."
}

